clear fz j i 
%% 表格2 数据读取

24 


B=xlsread('D:\QQPCmgr\Documents\国赛模拟\国赛
\CUMCM2017Problems\A\A 题附件.xls',2); 
X=1:size(B,2); 
Y=1:size(B,1); 
%% 计算小囿中心点 
for j=450:-1:50 
 if B(j,1)>B(j-1,1)&&B(j,1)>B(j+1,1) 
 fz(1)=j; 
 break; 
 end 
end 
for i=2:70 
 for j=fz(i-1)-5:fz(i-1)+5 
 if B(j,i)>B(j-1,i)&&B(j,i)>B(j+1,i) 
 fz(i)=j; 
 break 
 elseif j==(fz(i-1)+5) 
 fz(i)=fz(i-1)-2; 
 break; 
 end 
 end 
end 
for j=50:150 
 if B(j,180)>B(j-1,180)&&B(j,180)>B(j+1,180) 
 fz(180)=j; 
 break; 
 end 
end

